export function ibgeMunicipality(code: string | undefined): { name: string; state: string } | undefined {
  if (!code) return undefined;
  index ??= new Map(
    TABLE.split("\n").map((line) => {
      const [name = "", state = ""] = line.slice(7).split("|");
      return [line.slice(0, 7), { name, state }];
    }),
  );
  return index.get(code);
}
